#include <stdio.h>
#define OFFSET 6.0
int main(void) {
    const double factor = 0.5;
    double size = 8.0;
    double length = factor * size + OFFSET;
    printf("size=%.1f estimate=%.2f\n", size, length);
    return 0;
}

#include <stdio.h>
int main(void) {
    const double scale = 0.5;
    const double offset = 6.0;
    int size = 6;
    while (size <= 8) {
        double estimate = scale * size + offset;
        printf("%d:%.2f\n", size, estimate);
        size = size + 1;
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int first, second, third;
    first = second = third = 72;
    printf("%d %d %d\n", first, second, third);
    third = 69;
    printf("%d %d %d\n", first, second, third);
    return 0;
}

#include <stdio.h>
int main(void) {
    int number = 2;
    while (number <= 4) {
        printf("%d %d\n", number, number * number);
        number = number + 1;
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int cell = 1;
    double added = 2.0;
    double total = added;
    while (cell <= 4) {
        printf("%d %.0f %.0f\n", cell, added, total);
        cell = cell + 1;
        added = added * 2.0;
        total = total + added;
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    printf("int=%d real=%.2f negative=%d\n", 11 / 4, 11.0 / 4, -11 / 4);
    return 0;
}

#include <stdio.h>
int main(void) {
    int mirror, result;
    mirror = result = -(3 + 1) * 5 + (2 + 2 * (4 + 1));
    printf("%d %d\n", mirror, result);
    return 0;
}

#include <stdio.h>
int main(void) {
    int sample = 7;
    unsigned int type_bytes = sizeof(int);
    unsigned int object_bytes = sizeof sample;
    printf("type=%u object=%u value=%d\n", type_bytes, object_bytes, sample);
    return 0;
}

#include <stdio.h>
int main(void) {
    const int per_minute = 60;
    int seconds = 0;
    while (scanf("%d", &seconds) == 1 && seconds > 0) {
        printf("%d:%d\n", seconds / per_minute, seconds % per_minute);
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int left = 0;
    int right = 0;
    while (left < 3) {
        left++;
        ++right;
        printf("%d %d\n", left, right);
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int older = 4, newer = 4;
    int saved_old = older++;
    int saved_new = ++newer;
    printf("objects=%d,%d results=%d,%d\n", older, newer, saved_old, saved_new);
    return 0;
}

#include <stdio.h>
int main(void) {
    int remaining = 4;
    while (--remaining > 0) {
        printf("before=%d after=%d\n", remaining, remaining - 1);
    }
    printf("end=%d\n", remaining);
    return 0;
}

#include <stdio.h>
int main(void) {
    int index = 0;
    int total = 0;
    while (index < 6) {
        index = index + 1;
        total = total + index;
    }
    printf("count=%d sum=%d\n", index, total);
    return 0;
}

#include <stdio.h>
int main(void) {
    char marker = 'B';
    int code = marker;
    float copied = code;
    int truncated = -8.75;
    printf("%c %d %.2f %d\n", marker, code, copied, truncated);
    return 0;
}

#include <stdio.h>
void marks(int count);
int main(void) {
    int three = 3;
    char symbol = '!';
    float fractional = 2.75f;
    marks(three);
    marks(symbol);
    marks(fractional);
    return 0;
}
void marks(int count) {
    while (count > 0) {
        printf("*");
        count--;
    }
    printf("\n");
}

#include <stdio.h>
int main(void) {
    double km = 0.0;
    int minutes = 0, seconds = 0;
    if (scanf("%lf", &km) != 1) return 1;
    if (scanf("%d", &minutes) != 1) return 1;
    if (scanf("%d", &seconds) != 1) return 1;
    int elapsed = minutes * 60 + seconds;
    if (km <= 0.0 || elapsed <= 0) return 1;
    double miles = km * 0.62137;
    double mph = miles * 3600.0 / elapsed;
    int pace_seconds = (int)(elapsed / miles);
    printf("mph=%.2f pace=%d:%d\n", mph, pace_seconds / 60, pace_seconds % 60);
    return 0;
}

