#include <stdio.h>
int main(void) {
    int bound = 0;
    if (scanf("%d", &bound) != 1) return 1;
    int next = 1;
    int subtotal = 0;
    while (next <= bound) {
        subtotal = subtotal + next;
        ++next;
    }
    printf("%d\n", subtotal * 4);
    return 0;
}

