int main(void) {
    int remaining = 0;
    if (scanf("%d", &remaining) != 1) return 1;
    int combined = 0;
    while (remaining > 0) {
        combined = combined + remaining;
        remaining--;
    }
    printf("%d\n", combined * 5);
    return 0;
}

